import { readFileSync, writeFileSync } from "fs";
import { checkpoint } from "@tigrisdata/agent-kit";
import { getBucketInfo } from "@tigrisdata/storage";
import { Sha256 } from "@aws-crypto/sha256-js";
import { SignatureV4 } from "@smithy/signature-v4";

// Step 1: Read the build id
const buildId = readFileSync("/home/user/ckpt-tag/build_id.txt", "utf-8").trim();

// Step 2: Read the trial_id to construct the bucket name
const trialId = readFileSync("/logs/artifacts/trial_id", "utf-8").trim();
const bucketName = `harbor-pipeline-${trialId}`
  .toLowerCase()
  .replace(/[^a-z0-9-]/g, "-");

// Step 3: Compute unix timestamp
const unixTimestamp = Math.floor(Date.now() / 1000);

console.log(`Bucket: ${bucketName}`);
console.log(`Build ID: ${buildId}`);

// Ensure snapshots are enabled on the bucket
const infoResult = await getBucketInfo(bucketName);
if (infoResult.error) throw infoResult.error;

if (!infoResult.data.isSnapshotEnabled) {
  console.log("Enabling snapshots on bucket...");
  const accessKeyId = process.env.TIGRIS_STORAGE_ACCESS_KEY_ID ?? "";
  const secretAccessKey = process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY ?? "";
  const endpoint = process.env.TIGRIS_STORAGE_ENDPOINT ?? "REDACTED";

  const signer = new SignatureV4({
    credentials: { accessKeyId, secretAccessKey },
    region: "REDACTED",
    service: "s3",
    sha256: Sha256,
    uriEscapePath: false,
  });

  const body = JSON.stringify({ type: 1 }); // type 1 = snapshot-enabled bucket
  const url = new URL("/" + bucketName, endpoint);

  const signed = await signer.sign({
    method: "PATCH",
    protocol: url.protocol,
    hostname: url.hostname,
    path: url.pathname,
    headers: { "Content-Type": "application/json", host: url.host },
    body,
  });

  const resp = await fetch(url.toString(), {
    method: "PATCH",
    headers: signed.headers as Record<string, string>,
    body,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`Failed to enable snapshots: ${resp.status} ${text}`);
  }
  console.log("Snapshots enabled.");
} else {
  console.log("Snapshots already enabled.");
}

// Step 4: Take a named checkpoint
const name = `release-${buildId}-${unixTimestamp}`;
console.log(`Taking checkpoint with name: ${name}`);

const { data: ckpt, error } = await checkpoint(bucketName, { name });
if (error) throw error;

console.log(`Checkpoint created: snapshotId=${ckpt.snapshotId}`);

// Step 5: Persist the result
const result = {
  snapshotId: ckpt.snapshotId,
  name,
};

writeFileSync("/home/user/ckpt-tag/snapshot.json", JSON.stringify(result, null, 2));
console.log("snapshot.json written successfully.");
